def execute_agent_task(acad):
    counts = {}
    for obj in acad.doc.ModelSpace:
        name = str(getattr(obj, "ObjectName", "") or "").strip()
        if name:
            counts[name] = counts.get(name, 0) + 1
    if not counts:
        return {"transaction_type": "QUERY", "status": "SUCCESS", "data": "В чертеже нет объектов."}
    parts = [f"{k} ({v})" for k, v in sorted(counts.items(), key=lambda x: -x[1])]
    return {"transaction_type": "QUERY", "status": "SUCCESS", "data": "Типы объектов в чертеже: " + ", ".join(parts) + "."}

