def execute_agent_task(acad):
    import array
    sel = acad.doc.PickfirstSelectionSet
    if sel.Count == 0:
        return {"transaction_type": "QUERY", "status": "SUCCESS", "data": "Объект не выделен."}
    affected = []
    for i in range(sel.Count):
        obj = sel.Item(i)
        obj.Move(array.array("d", [0.0, 0.0, 0.0]), array.array("d", [50.0, 0.0, 0.0]))
        affected.append({"handle": str(obj.Handle), "type": str(obj.ObjectName)})
    return {"transaction_type": "COMMAND", "status": "SUCCESS", "affected_objects": affected}

