да, создай блок из выделенных объектов с.code:
def execute_agent_task(acad):
    # Получаем выделенные объекты
    selection = acad.doc.PickfirstSelectionSet

    if not selection:
        return {'transaction_type': 'QUERY', 'status': 'SUCCESS', 'data': 'Не выбрано ни одного объекта для создания блока.'}

    try:
        # Создаем новый блок в таблице блоков
        db = acad.doc.Database
        bt = db.BlockTable

        # Проверяем, существует ли уже блок с таким именем
        block_name = "Примитивы"
        if block_name in bt:
            return {'transaction_type': 'QUERY', 'status': 'SUCCESS', 'data': f'Блок с именем "{block_name}" уже существует.'}

        # Создаем новый блок
        new_block_id = bt.Add(block_name)
        new_block = db.BlockTableRecord(new_block_id)

        # Копируем выделенные объекты в новый блок
        for obj in selection:
            copied_obj = obj.Copy()
            new_block.AppendEntity(copied_obj)

        return {'transaction_type': 'COMMAND', 'status': 'SUCCESS', 'affected_objects': [{'handle': str(new_block_id), 'type': 'AcDbBlockTableRecord'}]}
    except Exception as e:
        return {'transaction_type': 'QUERY', 'status': 'SUCCESS', 'data': f'Ошибка при создании блока: {str(e)}'}

